/* ClackOS events — the shared reader behind the Calendar app and the desktop's
 * upcoming-events pull-down.
 *
 * Two sources, both plain files under content/applications/calendar/:
 *   events.csv  the website's own events, hand-kept or edited in the Calendar
 *               app and committed from it
 *   luma.json   a read-only mirror of the events hosted on Luma, regenerated by
 *               scripts/fetch_luma_events.py (Luma sends no CORS headers, so the
 *               browser cannot fetch the profile itself)
 *
 * Only the Calendar app writes anything back, and only ever events.csv, which is
 * why every event carries the source it came from.
 *
 * Dates are local YYYY-MM-DD strings throughout, so comparing two days is a
 * string compare and no timezone can shift an event onto the wrong date. Times
 * are wall-clock where the event happens, the way both sources record them.
 *
 *   <script src="assets/js/events.js"></script>
 *   const { events } = await ClackOSEvents.load();
 */
(() => {
/* Paths are resolved against the site root, worked out from this script's own
 * URL, so the module reads the same files from index.html and from an app page
 * two folders down. */
const SITE_ROOT = new URL('../../', document.currentScript.src);
const CSV_PATH = 'content/applications/calendar/events.csv';
const LUMA_PATH = 'content/applications/calendar/luma.json';
const COLUMNS = ['title', 'date', 'end', 'location', 'map', 'notes'];

const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June',
  'July', 'August', 'September', 'October', 'November', 'December'];
const SHORT_MONTHS = MONTHS.map(name => name.slice(0, 3));
const SHORT_DAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];

let eventSeq = 0;

/* ---------------- dates ---------------- */
const pad = n => String(n).padStart(2, '0');
const isoOf = date => `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}`;
const dateOf = iso => { const [y, m, d] = iso.split('-').map(Number); return new Date(y, m - 1, d); };
const todayIso = () => isoOf(new Date());
const shiftIso = (iso, days) => {
  const date = dateOf(iso);
  date.setDate(date.getDate() + days);
  return isoOf(date);
};

const STAMP_RE = /^(\d{4})-(\d{2})-(\d{2})(?:[T ]+(\d{1,2}):(\d{2}))?$/;
const TIME_RE = /^(\d{1,2}):(\d{2})$/;

/* "2026-08-14", "2026-08-14 19:30" and "2026-08-14T19:30" all parse; anything
 * else (including 31 February) does not. */
function parseStamp(value) {
  const match = STAMP_RE.exec(String(value ?? '').trim());
  if (!match) return null;
  const [, year, month, day, hour, minute] = match;
  const date = new Date(+year, +month - 1, +day);
  if (date.getMonth() !== +month - 1 || date.getDate() !== +day) return null;
  if (hour !== undefined && +hour > 23) return null;
  return { iso: `${year}-${month}-${day}`, time: hour === undefined ? '' : `${pad(+hour)}:${minute}` };
}

function parseTime(value) {
  const match = TIME_RE.exec(String(value ?? '').trim());
  if (!match || +match[1] > 23) return '';
  return `${pad(+match[1])}:${match[2]}`;
}

const startStamp = event => event.date + (event.time ? ' ' + event.time : '');
const endStamp = event => {
  if (event.endDate === event.date && !event.endTime) return '';
  return event.endDate + (event.endTime ? ' ' + event.endTime : '');
};
const sortKey = event => event.date + 'T' + (event.time || '00:00') + ' ' + event.title.toLowerCase();
const byWhen = (a, b) => (sortKey(a) < sortKey(b) ? -1 : sortKey(a) > sortKey(b) ? 1 : 0);

/* "Fri 14 Aug 2026" */
function formatDay(iso, withYear = true) {
  const date = dateOf(iso);
  return `${SHORT_DAYS[date.getDay()]} ${date.getDate()} ${SHORT_MONTHS[date.getMonth()]}`
    + (withYear ? ` ${date.getFullYear()}` : '');
}

/* "25th July", for the desktop's date pill */
function formatLongDay(iso) {
  const date = dateOf(iso);
  const day = date.getDate();
  const teenth = day % 100 >= 11 && day % 100 <= 13;
  const suffix = teenth ? 'th' : ({ 1: 'st', 2: 'nd', 3: 'rd' })[day % 10] || 'th';
  return `${day}${suffix} ${MONTHS[date.getMonth()]}`;
}

/* "Fri 14 Aug 2026, 19:30", "Fri 14 Aug 2026, 19:30 – 22:00",
 * "Fri 14 Aug – Sun 16 Aug 2026" */
function describeWhen(event) {
  const sameYear = event.date.slice(0, 4) === event.endDate.slice(0, 4);
  if (event.endDate === event.date) {
    const times = [event.time, event.endTime].filter(Boolean).join(' – ');
    return formatDay(event.date) + (times ? `, ${times}` : '');
  }
  const from = formatDay(event.date, !sameYear) + (event.time ? ` ${event.time}` : '');
  const to = formatDay(event.endDate) + (event.endTime ? ` ${event.endTime}` : '');
  return `${from} – ${to}`;
}

/* ---------------- links ----------------
 * http(s) and mailto only, plus site-relative paths where the caller allows
 * them. Anything with another scheme — javascript:, data: — is dropped. */
function safeUrl(value, allowRelative = false) {
  const raw = String(value ?? '').trim();
  if (!raw) return '';
  if (/^(?:https?|mailto):/i.test(raw)) {
    try { return new URL(raw).href; } catch { return ''; }
  }
  if (allowRelative && !/^[a-z][a-z0-9+.-]*:/i.test(raw) && !raw.startsWith('//')) return raw;
  return '';
}

/* An explicit map link wins; otherwise the location text becomes a Maps search. */
function mapLink(event) {
  const explicit = safeUrl(event.map);
  if (explicit) return explicit;
  if (!event.location.trim()) return '';
  return 'https://www.google.com/maps/search/?api=1&query=' + encodeURIComponent(event.location.trim());
}

/* ---------------- CSV ----------------
 * RFC 4180: quoted fields may hold commas, quotes ("") and newlines, which is
 * what lets a whole markdown note live in one cell. */
function parseCsv(text) {
  const source = String(text).replace(/^\uFEFF/, '');
  const rows = [];
  let row = [];
  let field = '';
  let quoted = false;
  let started = false;                   /* this row has at least one cell */
  for (let i = 0; i < source.length; i++) {
    const char = source[i];
    if (quoted) {
      if (char !== '"') { field += char; continue; }
      if (source[i + 1] === '"') { field += '"'; i++; continue; }
      quoted = false;
      continue;
    }
    if (char === '"' && field === '') { quoted = true; started = true; continue; }
    if (char === ',') { row.push(field); field = ''; started = true; continue; }
    if (char === '\r') continue;
    if (char === '\n') {
      if (started || field) { row.push(field); rows.push(row); }
      row = []; field = ''; started = false;
      continue;
    }
    field += char;
    started = true;
  }
  if (started || field) { row.push(field); rows.push(row); }
  return rows;
}

/* Columns are matched by header name, so the file can carry them in any order
 * and gain extra ones without upsetting anything. */
function eventsFromCsv(text) {
  const rows = parseCsv(text).filter(row => row.some(cell => cell.trim()));
  if (!rows.length) return { list: [], skipped: 0 };
  const header = rows[0].map(cell => cell.trim().toLowerCase());
  const index = {};
  for (const name of COLUMNS) index[name] = header.indexOf(name);
  if (index.date === -1 || index.title === -1)
    throw new Error('The CSV needs at least a "title" and a "date" column.');
  const list = [];
  let skipped = 0;
  for (const row of rows.slice(1)) {
    const cell = name => (index[name] === -1 ? '' : (row[index[name]] ?? '')).trim();
    const event = fromRecord({
      title: cell('title'), date: cell('date'), end: cell('end'),
      location: cell('location'), map: cell('map'),
      notes: (index.notes === -1 ? '' : (row[index.notes] ?? '')).replace(/\r\n?/g, '\n').trim()
    }, 'csv');
    if (event) list.push(event); else skipped++;
  }
  return { list, skipped };
}

/* The Luma mirror. Its stamps are already local wall-clock in the event's own
 * timezone, the same shape the CSV uses, so both go through fromRecord. */
function eventsFromLuma(payload) {
  const list = [];
  let skipped = 0;
  for (const record of Array.isArray(payload?.events) ? payload.events : []) {
    const event = fromRecord(record, 'luma');
    if (event) list.push(event); else skipped++;
  }
  return { list, skipped, source: safeUrl(payload?.source) };
}

/* One record — a CSV row or a mirror entry — as the event shape everything
 * uses. Null when there is no usable date, which is the one thing an event
 * needs. */
function fromRecord(record, source) {
  const start = parseStamp(record.date);
  if (!start) return null;
  const rawEnd = String(record.end ?? '').trim();
  const end = parseStamp(rawEnd) || (parseTime(rawEnd) ? { iso: start.iso, time: parseTime(rawEnd) } : null);
  return {
    id: ++eventSeq,
    source,
    title: String(record.title ?? '').trim() || 'Untitled event',
    date: start.iso,
    time: start.time,
    endDate: end && end.iso >= start.iso ? end.iso : start.iso,
    endTime: end ? end.time : '',
    location: String(record.location ?? '').trim(),
    map: String(record.map ?? '').trim(),
    notes: String(record.notes ?? '').trim(),
    url: safeUrl(record.url)
  };
}

const isOwn = event => event.source !== 'luma';

/* The CSV wins a clash: a hand-written entry for the same day and title is
 * there to say more than the mirror does. */
function mergeSources(own, mirrored) {
  const claimed = new Set(own.map(event => `${event.date} ${event.title.toLowerCase()}`));
  return [...own, ...mirrored.filter(event => !claimed.has(`${event.date} ${event.title.toLowerCase()}`))];
}

const fresh = path => new URL(`${path}?_clack=${Date.now()}`, SITE_ROOT);

/* Both sources, merged. The CSV is the calendar; the mirror is a bonus that is
 * simply missing until the workflow has run once, so a failure there never
 * costs the caller its own events. */
async function load() {
  const result = {
    events: [], own: [], mirrored: [],
    lumaSource: '', skipped: 0, csvError: '', lumaError: ''
  };

  try {
    const res = await fetch(fresh(LUMA_PATH), { cache: 'no-store' });
    if (res.ok) {
      const { list, source } = eventsFromLuma(await res.json());
      result.mirrored = list;
      result.lumaSource = source;
    } else if (res.status !== 404) {
      result.lumaError = `Could not load the Luma mirror (${res.status}).`;
    }
  } catch (error) {
    result.lumaError = 'The Luma events could not be read.';
    console.warn(error);
  }

  try {
    const res = await fetch(fresh(CSV_PATH), { cache: 'no-store' });
    if (!res.ok) throw new Error(`Could not load the events CSV (${res.status}).`);
    const { list, skipped } = eventsFromCsv(await res.text());
    result.own = list;
    result.skipped = skipped;
  } catch (error) {
    result.csvError = error.message;
    console.warn(error);
  }

  result.events = mergeSources(result.own, result.mirrored);
  return result;
}

/* Everything from today onwards — an event running over today still counts as
 * on — soonest first. */
function upcoming(events, limit = 0) {
  const today = todayIso();
  const list = events.filter(event => event.endDate >= today).sort(byWhen);
  return limit > 0 ? list.slice(0, limit) : list;
}

window.ClackOSEvents = {
  CSV_PATH, LUMA_PATH, COLUMNS, MONTHS, SHORT_MONTHS, SHORT_DAYS,
  load, upcoming, eventsFromCsv, eventsFromLuma, fromRecord, mergeSources, isOwn,
  parseCsv, parseStamp, parseTime, startStamp, endStamp, byWhen,
  isoOf, dateOf, todayIso, shiftIso, pad,
  formatDay, formatLongDay, describeWhen, safeUrl, mapLink,
  nextId: () => ++eventSeq
};
})();
